insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('caa984b6-fa9b-45d4-852d-5e2eeb5221b3', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', null, 'topic'::public.curated_course_node_type, 'What Are the Humanities? Questions, Methods, and Human Meaning', 'This opening unit defines the humanities as disciplines that study meaning, value, expression, memory, and human experience. Students learn why literature, philosophy, art, history, religion, music, performance, and language remain essential for interpreting culture and modern life.', 0),
  ('2946eb4f-27d6-4347-bdfa-f245b7e528c6', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'caa984b6-fa9b-45d4-852d-5e2eeb5221b3', 'subtopic'::public.curated_course_node_type, 'The scope of humanistic study', 'Students learn what distinguishes humanities inquiry from scientific and social-scientific explanation while also seeing where the fields overlap.', 0),
  ('9645575b-ab00-4ce8-949a-d10e011bbfa1', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '2946eb4f-27d6-4347-bdfa-f245b7e528c6', 'concept'::public.curated_course_node_type, 'Meaning, value, interpretation, and form', null, 0),
  ('59bd6aa9-0d39-49b5-bf9e-7297ae6e2052', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '2946eb4f-27d6-4347-bdfa-f245b7e528c6', 'concept'::public.curated_course_node_type, 'Texts, artifacts, performances, images, and places', null, 1),
  ('0ac45513-10f3-4edb-9de2-f2c60a7c9715', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '2946eb4f-27d6-4347-bdfa-f245b7e528c6', 'concept'::public.curated_course_node_type, 'Humanistic questions about identity, justice, mortality, beauty, and belonging', null, 2),
  ('6d82bdea-3f04-494e-acba-9d03ff944a8b', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '2946eb4f-27d6-4347-bdfa-f245b7e528c6', 'concept'::public.curated_course_node_type, 'Connections to liberal arts education', null, 3),
  ('1c6a7ed1-ab99-47d0-aabf-433461b5ff4c', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'caa984b6-fa9b-45d4-852d-5e2eeb5221b3', 'subtopic'::public.curated_course_node_type, 'Humanities as methods of attention', 'The point is to cultivate careful noticing before judgment: reading, listening, looking, comparing, and contextualizing.', 1),
  ('c8598667-50fc-4701-bf9f-15ba4cdde364', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '1c6a7ed1-ab99-47d0-aabf-433461b5ff4c', 'concept'::public.curated_course_node_type, 'Slow reading and close looking', null, 0),
  ('437c2c62-76e7-435a-8a69-fed610cf845c', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '1c6a7ed1-ab99-47d0-aabf-433461b5ff4c', 'concept'::public.curated_course_node_type, 'Description before interpretation', null, 1),
  ('9199d2f9-4d3d-4a4e-a677-6ce2e47f6d3c', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '1c6a7ed1-ab99-47d0-aabf-433461b5ff4c', 'concept'::public.curated_course_node_type, 'Historical and cultural framing', null, 2),
  ('33ce7cea-7237-44d9-9bac-4ad12ba8b0f7', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '1c6a7ed1-ab99-47d0-aabf-433461b5ff4c', 'concept'::public.curated_course_node_type, 'Ambiguity, evidence, and multiple meanings', null, 3),
  ('bfc70754-f2b9-485c-ba06-1b78ea5e4397', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'caa984b6-fa9b-45d4-852d-5e2eeb5221b3', 'subtopic'::public.curated_course_node_type, 'Why the humanities matter now', 'Students connect the humanities to public life, democratic dialogue, ethical judgment, creativity, and self-understanding.', 2),
  ('f356dcfb-34a4-428c-8aa1-2e9607fd8b7d', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'bfc70754-f2b9-485c-ba06-1b78ea5e4397', 'concept'::public.curated_course_node_type, 'Citizenship and civic imagination', null, 0),
  ('50aca8ef-3a8f-442f-9f69-23978f121e97', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'bfc70754-f2b9-485c-ba06-1b78ea5e4397', 'concept'::public.curated_course_node_type, 'Empathy and perspective-taking', null, 1),
  ('4d3f3272-4fb4-4368-a073-5053c4a676f1', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'bfc70754-f2b9-485c-ba06-1b78ea5e4397', 'concept'::public.curated_course_node_type, 'Cultural memory and public debate', null, 2),
  ('42f21ee4-d633-4aae-adbf-f994d8920d86', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'bfc70754-f2b9-485c-ba06-1b78ea5e4397', 'concept'::public.curated_course_node_type, 'Humanistic skills in contemporary careers', null, 3),
  ('34c03ea5-1517-48cf-bd1e-3428030acd83', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', null, 'topic'::public.curated_course_node_type, 'Humanistic Inquiry: Close Reading, Interpretation, Context, and Argument', 'This unit gives students the toolkit for doing humanities work. They practice turning observation into interpretation, interpretation into argument, and argument into clear academic writing.', 1),
  ('26546832-b1c8-4981-9875-4e9e67ba3d85', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '34c03ea5-1517-48cf-bd1e-3428030acd83', 'subtopic'::public.curated_course_node_type, 'Close reading and close looking', 'Students learn to build interpretations from specific evidence rather than broad impressions.', 0),
  ('b5b2ab73-79a4-4c76-925c-e3a744977b20', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '26546832-b1c8-4981-9875-4e9e67ba3d85', 'concept'::public.curated_course_node_type, 'Diction, image, metaphor, structure, and genre', null, 0),
  ('8be17831-8017-454c-8224-eb657bcd8eb8', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '26546832-b1c8-4981-9875-4e9e67ba3d85', 'concept'::public.curated_course_node_type, 'Composition, line, color, material, and scale', null, 1),
  ('2f804f09-32cf-45e6-810b-dc450e38f005', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '26546832-b1c8-4981-9875-4e9e67ba3d85', 'concept'::public.curated_course_node_type, 'Sound, rhythm, gesture, and performance detail', null, 2),
  ('d9877ae5-8ae2-4f5d-b85b-81c27e8a38ca', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '26546832-b1c8-4981-9875-4e9e67ba3d85', 'concept'::public.curated_course_node_type, 'Patterns, tensions, and anomalies', null, 3),
  ('975177f2-a165-450b-8d50-f4b16cd050b2', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '34c03ea5-1517-48cf-bd1e-3428030acd83', 'subtopic'::public.curated_course_node_type, 'Context and historical method', 'Students learn that works are made inside worlds: institutions, languages, audiences, technologies, and power relations.', 1),
  ('57f585e6-88ce-4fed-9fcb-87401691ad0f', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '975177f2-a165-450b-8d50-f4b16cd050b2', 'concept'::public.curated_course_node_type, 'Author, maker, patron, and audience', null, 0),
  ('56a9604b-df12-466a-a4e3-ed858f5e0402', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '975177f2-a165-450b-8d50-f4b16cd050b2', 'concept'::public.curated_course_node_type, 'Period, place, movement, and medium', null, 1),
  ('73b21331-9f7f-4150-b2f9-00bb9f4acbe2', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '975177f2-a165-450b-8d50-f4b16cd050b2', 'concept'::public.curated_course_node_type, 'Reception and changing interpretation', null, 2),
  ('b1b9ae3e-0291-4448-abb4-34843eab9636', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '975177f2-a165-450b-8d50-f4b16cd050b2', 'concept'::public.curated_course_node_type, 'Archives and primary sources', null, 3),
  ('ad3baee6-ef01-44e6-9c87-26721a43d08c', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '34c03ea5-1517-48cf-bd1e-3428030acd83', 'subtopic'::public.curated_course_node_type, 'Argument and scholarly conversation', 'The gist is learning to enter a debate responsibly, with claims, evidence, warrants, and respectful disagreement.', 2),
  ('02396f8a-074d-4e47-8fde-31d51ef72dee', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'ad3baee6-ef01-44e6-9c87-26721a43d08c', 'concept'::public.curated_course_node_type, 'Research questions and thesis statements', null, 0),
  ('2e0bde40-b1fa-47c9-80f9-ef6fbc01db7e', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'ad3baee6-ef01-44e6-9c87-26721a43d08c', 'concept'::public.curated_course_node_type, 'Evidence selection and explanation', null, 1),
  ('187014fc-b7f0-4258-ad4f-1d7cb26d5381', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'ad3baee6-ef01-44e6-9c87-26721a43d08c', 'concept'::public.curated_course_node_type, 'Counterargument and revision', null, 2),
  ('38c150d8-e19c-4dbc-b761-faf45cda182f', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'ad3baee6-ef01-44e6-9c87-26721a43d08c', 'concept'::public.curated_course_node_type, 'Citation and academic integrity', null, 3),
  ('21b5e6e6-5fdb-4b9e-9bf3-2f3507a1cd51', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', null, 'topic'::public.curated_course_node_type, 'Literature as World-Making: Poetry, Narrative, Drama, and Myth', 'Literature gives students practice interpreting language as art, memory, thought, and social imagination. The unit treats literary works as crafted forms that build worlds, voices, conflicts, and ethical possibilities.', 2),
  ('08ca7da2-eafb-453c-9483-6585747b88bb', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '21b5e6e6-5fdb-4b9e-9bf3-2f3507a1cd51', 'subtopic'::public.curated_course_node_type, 'Poetry and compressed language', 'Students learn how poems make meaning through rhythm, image, sound, form, and silence.', 0),
  ('294fc7bf-fbef-4111-827c-35c492bfc6c4', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '08ca7da2-eafb-453c-9483-6585747b88bb', 'concept'::public.curated_course_node_type, 'Speaker, tone, and address', null, 0),
  ('b4a47046-d42b-4da0-9cd7-22568efdc048', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '08ca7da2-eafb-453c-9483-6585747b88bb', 'concept'::public.curated_course_node_type, 'Figurative language and imagery', null, 1),
  ('a27a7b2f-671c-4e71-b4c9-d879b45313c7', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '08ca7da2-eafb-453c-9483-6585747b88bb', 'concept'::public.curated_course_node_type, 'Form, meter, line, and stanza', null, 2),
  ('43d28f2a-4ac5-4f95-8353-ecf66af51039', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '08ca7da2-eafb-453c-9483-6585747b88bb', 'concept'::public.curated_course_node_type, 'Translation and performance', null, 3),
  ('7c368f92-49c5-4579-a2af-95ca954477df', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '21b5e6e6-5fdb-4b9e-9bf3-2f3507a1cd51', 'subtopic'::public.curated_course_node_type, 'Narrative and fiction', 'Students examine how stories organize time, causality, character, perspective, and moral complexity.', 1),
  ('1aa7c6f4-babd-4a02-985c-41cea44fe648', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '7c368f92-49c5-4579-a2af-95ca954477df', 'concept'::public.curated_course_node_type, 'Plot, scene, and structure', null, 0);
