  ('293af96e-e70e-47e8-b3bc-0ba2e9a4c325', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '7c368f92-49c5-4579-a2af-95ca954477df', 'concept'::public.curated_course_node_type, 'World-building and social context', null, 3),
