  ('f548ff5a-a29b-4dbf-8d60-763a95c5e1a7', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '800f5096-b836-4d71-90a7-ddc9c1d4b4a5', 'concept'::public.curated_course_node_type, 'Performance, audience, and embodiment', null, 2),
  ('b81a2ef6-60b4-4abd-8349-bc21e6b86fbd', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '800f5096-b836-4d71-90a7-ddc9c1d4b4a5', 'concept'::public.curated_course_node_type, 'Adaptation and reinterpretation', null, 3),
  ('22fa60a8-4963-419d-bdb3-bc568c0132f8', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', null, 'topic'::public.curated_course_node_type, 'Philosophy and the History of Ideas: Reality, Knowledge, Ethics, and the Self', 'Philosophy teaches students to ask precise questions, test assumptions, and evaluate reasons. This unit introduces major philosophical problems that shape humanistic inquiry across periods and cultures.', 3),
  ('67a656ea-5d41-46fe-bd0b-6476abf48a05', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '22fa60a8-4963-419d-bdb3-bc568c0132f8', 'subtopic'::public.curated_course_node_type, 'Reality, knowledge, and skepticism', 'Students learn how philosophers question what exists, what can be known, and how belief can be justified.', 0),
  ('5b1bef6c-3469-4f59-9851-0d637fff3e9d', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '67a656ea-5d41-46fe-bd0b-6476abf48a05', 'concept'::public.curated_course_node_type, 'Metaphysics and being', null, 0),
  ('fc072107-efec-440e-b5d7-e6649d693f74', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '67a656ea-5d41-46fe-bd0b-6476abf48a05', 'concept'::public.curated_course_node_type, 'Epistemology and evidence', null, 1),
  ('ad432ec5-9223-4412-abb4-5409fc7f770f', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '67a656ea-5d41-46fe-bd0b-6476abf48a05', 'concept'::public.curated_course_node_type, 'Skepticism and certainty', null, 2),
  ('2e934095-de01-42b0-8202-1f71dad74cc7', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '67a656ea-5d41-46fe-bd0b-6476abf48a05', 'concept'::public.curated_course_node_type, 'Mind, body, and self', null, 3),
  ('9a3560ab-c6a4-470b-b7a1-4b8db7bfc1c8', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '22fa60a8-4963-419d-bdb3-bc568c0132f8', 'subtopic'::public.curated_course_node_type, 'Ethics and moral reasoning', 'Students practice comparing frameworks for judgment and applying them to difficult human situations.', 1),
  ('097d414b-5968-47e0-a72a-3eacc79d396a', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '9a3560ab-c6a4-470b-b7a1-4b8db7bfc1c8', 'concept'::public.curated_course_node_type, 'Virtue ethics', null, 0),
  ('1587b7af-1375-43e3-b7b7-47aec1c18745', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '9a3560ab-c6a4-470b-b7a1-4b8db7bfc1c8', 'concept'::public.curated_course_node_type, 'Deontology and duty', null, 1),
  ('e9090a61-2a46-44d2-9553-28686fbef709', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '9a3560ab-c6a4-470b-b7a1-4b8db7bfc1c8', 'concept'::public.curated_course_node_type, 'Consequentialism', null, 2),
  ('af66f385-490d-4a9a-aa0a-4a3259fec359', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '9a3560ab-c6a4-470b-b7a1-4b8db7bfc1c8', 'concept'::public.curated_course_node_type, 'Care, responsibility, and applied ethics', null, 3),
  ('05654193-24e9-43c0-9fde-66bbb0a95e07', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '22fa60a8-4963-419d-bdb3-bc568c0132f8', 'subtopic'::public.curated_course_node_type, 'Political philosophy and justice', 'The unit connects ideas about the good life to institutions, rights, authority, and public life.', 2),
  ('14ee292a-4f47-4e61-aa90-69081f69ad64', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '05654193-24e9-43c0-9fde-66bbb0a95e07', 'concept'::public.curated_course_node_type, 'Liberty, equality, and rights', null, 0),
  ('9efda216-830c-4a59-8b64-0566e9d99d6d', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '05654193-24e9-43c0-9fde-66bbb0a95e07', 'concept'::public.curated_course_node_type, 'Authority and legitimacy', null, 1),
  ('8eea75f8-a34d-4341-9358-11a17171cf48', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '05654193-24e9-43c0-9fde-66bbb0a95e07', 'concept'::public.curated_course_node_type, 'Justice and distribution', null, 2),
  ('f2a5bdec-ecc7-4a98-a215-e80dec6a48e1', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '05654193-24e9-43c0-9fde-66bbb0a95e07', 'concept'::public.curated_course_node_type, 'Democracy, citizenship, and dissent', null, 3),
  ('e4d88fd6-a22e-4137-8b3d-9d3061f21426', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', null, 'topic'::public.curated_course_node_type, 'Visual Arts and Architecture: Seeing, Form, Space, and Power', 'This unit trains visual literacy. Students learn to interpret images, objects, buildings, and spaces as cultural arguments shaped by materials, techniques, patrons, audiences, and histories.', 4),
  ('8965745d-b48a-4c01-bd3c-b2af2995ffae', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'e4d88fd6-a22e-4137-8b3d-9d3061f21426', 'subtopic'::public.curated_course_node_type, 'Formal visual analysis', 'Students learn to describe what they see with precision before moving into meaning.', 0),
  ('dde9130c-9a38-4ff8-bdf5-01e0ccc0411e', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '8965745d-b48a-4c01-bd3c-b2af2995ffae', 'concept'::public.curated_course_node_type, 'Line, color, light, texture, and composition', null, 0),
