  ('657d291e-c3e0-4c2b-a13e-992ed4428963', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'b96ffe8d-2872-4158-83ea-7bda3fb86a68', 'concept'::public.curated_course_node_type, 'Collection and provenance', null, 0),
