insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('799fb55c-279d-4087-81f9-21d04583e381', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', null, 'topic'::public.curated_course_node_type, 'Music, Theater, Performance, and Embodied Culture', 'Humanities study is not only textual or visual. This unit examines live, embodied, and sonic forms that create meaning through voice, movement, time, audience, and ritual.', 5),
  ('30eb67e6-bffa-4598-857a-a7c63e7e2685', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '799fb55c-279d-4087-81f9-21d04583e381', 'subtopic'::public.curated_course_node_type, 'Music and listening', 'Students learn to discuss music as patterned sound with cultural, emotional, and historical force.', 0),
  ('e4239f69-e8e5-45d6-bee1-03c8ea93e0f0', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '30eb67e6-bffa-4598-857a-a7c63e7e2685', 'concept'::public.curated_course_node_type, 'Melody, rhythm, harmony, timbre, and texture', null, 0),
