  ('df4e3748-580b-4ae9-b689-16e000882901', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '799fb55c-279d-4087-81f9-21d04583e381', 'subtopic'::public.curated_course_node_type, 'Theater and performance', 'Students study performance as an event made by bodies, spaces, texts, audiences, and conventions.', 1),
  ('a9b13adf-f0f8-46f3-9b18-d9c69ef58dab', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'df4e3748-580b-4ae9-b689-16e000882901', 'concept'::public.curated_course_node_type, 'Script, staging, and dramaturgy', null, 0),
  ('4f711112-39a2-4cb0-a5e5-e1a5a50704bf', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'df4e3748-580b-4ae9-b689-16e000882901', 'concept'::public.curated_course_node_type, 'Gesture, voice, costume, and set', null, 1),
