  ('7a742e9f-014a-497b-928c-32b63f8f01f0', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'df4e3748-580b-4ae9-b689-16e000882901', 'concept'::public.curated_course_node_type, 'Performance traditions across cultures', null, 3),
  ('f8e6a5a6-730c-48b5-a57e-b649a5c1a59a', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '799fb55c-279d-4087-81f9-21d04583e381', 'subtopic'::public.curated_course_node_type, 'Embodiment and cultural practice', 'The goal is to recognize that culture is enacted, repeated, improvised, and contested through bodies.', 2),
  ('be8fa72e-a616-4914-96f7-9a8bb5ed93d7', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'f8e6a5a6-730c-48b5-a57e-b649a5c1a59a', 'concept'::public.curated_course_node_type, 'Ritual and ceremony', null, 0),
  ('10e58992-7876-4bfa-b903-b9df5a874b82', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'f8e6a5a6-730c-48b5-a57e-b649a5c1a59a', 'concept'::public.curated_course_node_type, 'Dance and movement', null, 1),
  ('a8c0b07f-131c-4f02-976e-3d55b607967c', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'f8e6a5a6-730c-48b5-a57e-b649a5c1a59a', 'concept'::public.curated_course_node_type, 'Everyday performance and identity', null, 2),
  ('5e376d9b-37d4-421f-bc35-e36ab9106ee9', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'f8e6a5a6-730c-48b5-a57e-b649a5c1a59a', 'concept'::public.curated_course_node_type, 'Documentation and performance archives', null, 3),
  ('63ae2170-eb7c-4eb3-92ff-221966c089e1', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', null, 'topic'::public.curated_course_node_type, 'History, Memory, Archives, and Cultural Context', 'History gives humanities students a disciplined way to study change over time. This unit distinguishes memory from evidence, narrative from archive, and interpretation from mere chronology.', 6),
  ('632da7e2-74b2-43ab-9661-73c00ada3369', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '63ae2170-eb7c-4eb3-92ff-221966c089e1', 'subtopic'::public.curated_course_node_type, 'Historical thinking', 'Students learn to analyze causation, contingency, continuity, change, and periodization.', 0),
  ('0028af8f-dd0b-4030-af15-1d63d168add5', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '632da7e2-74b2-43ab-9661-73c00ada3369', 'concept'::public.curated_course_node_type, 'Chronology and periodization', null, 0),
  ('2248a9c3-bdd5-4f7e-9f54-459d22d4b8ff', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '632da7e2-74b2-43ab-9661-73c00ada3369', 'concept'::public.curated_course_node_type, 'Cause, consequence, and contingency', null, 1),
  ('6ad5aaee-2073-4161-a314-2a1113db0bbd', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '632da7e2-74b2-43ab-9661-73c00ada3369', 'concept'::public.curated_course_node_type, 'Comparison across places and periods', null, 2),
  ('b2507c7d-66c0-48ad-8e5b-a38b7cd567f0', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '632da7e2-74b2-43ab-9661-73c00ada3369', 'concept'::public.curated_course_node_type, 'Microhistory and global history', null, 3),
  ('da7efa1c-cd81-45ed-a2fe-3342ba4c1691', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '63ae2170-eb7c-4eb3-92ff-221966c089e1', 'subtopic'::public.curated_course_node_type, 'Archives and primary sources', 'Students practice reading historical evidence as partial, situated, and often contested.', 1),
  ('4a4bc01e-f1cd-494e-9e43-76410928df1e', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'da7efa1c-cd81-45ed-a2fe-3342ba4c1691', 'concept'::public.curated_course_node_type, 'Manuscripts, letters, images, maps, and objects', null, 0),
  ('1d881805-96d1-4b2f-8d1c-28621c0201eb', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'da7efa1c-cd81-45ed-a2fe-3342ba4c1691', 'concept'::public.curated_course_node_type, 'Source criticism and bias', null, 1),
  ('fadb71c5-b517-4972-bc6d-f1beb81a35ce', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'da7efa1c-cd81-45ed-a2fe-3342ba4c1691', 'concept'::public.curated_course_node_type, 'Silences in the archive', null, 2),
  ('14223d27-4984-439a-9727-698f0e9ab462', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'da7efa1c-cd81-45ed-a2fe-3342ba4c1691', 'concept'::public.curated_course_node_type, 'Oral history and lived memory', null, 3),
