  ('410db3ff-8ab6-4ede-90b6-88db2bedb539', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'aee17fe5-bc3c-40f0-ac5e-0eb7b1db1a5a', 'concept'::public.curated_course_node_type, 'Monuments and memorials', null, 0),
  ('e4091460-dee6-48b3-b4cf-4a9ac94d4595', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'aee17fe5-bc3c-40f0-ac5e-0eb7b1db1a5a', 'concept'::public.curated_course_node_type, 'Museums and heritage sites', null, 1),
  ('8df803b5-8ced-48f3-b46d-87153f3a7be4', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'aee17fe5-bc3c-40f0-ac5e-0eb7b1db1a5a', 'concept'::public.curated_course_node_type, 'Trauma, testimony, and remembrance', null, 2),
  ('cf2f1db4-fbec-4c88-ace6-b19644592dd9', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'aee17fe5-bc3c-40f0-ac5e-0eb7b1db1a5a', 'concept'::public.curated_course_node_type, 'History in public controversy', null, 3),
  ('89322b0f-4140-4f17-b229-24f7dfea0dba', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', null, 'topic'::public.curated_course_node_type, 'Religion, Myth, Ritual, and Meaning-Making', 'Religious and mythic traditions are central to humanistic study because they shape art, literature, ethics, politics, time, community, and ideas of the sacred. This unit approaches religion academically, comparatively, and respectfully.', 7),
  ('d0dd2f88-8c9f-4fa2-8cad-6816d957023a', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '89322b0f-4140-4f17-b229-24f7dfea0dba', 'subtopic'::public.curated_course_node_type, 'Academic study of religion', 'Students learn to analyze religion without reducing it to belief alone or evaluating it devotionally.', 0),
  ('a101653b-504b-40c7-92b7-fd328abb3683', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'd0dd2f88-8c9f-4fa2-8cad-6816d957023a', 'concept'::public.curated_course_node_type, 'Myth, ritual, doctrine, ethics, and community', null, 0),
  ('57af8305-932a-4eae-a112-42ab7142e6c1', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'd0dd2f88-8c9f-4fa2-8cad-6816d957023a', 'concept'::public.curated_course_node_type, 'Insider and outsider perspectives', null, 1),
  ('c29faaae-00e6-481f-9963-75aca690ad6c', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'd0dd2f88-8c9f-4fa2-8cad-6816d957023a', 'concept'::public.curated_course_node_type, 'Text, practice, material culture, and lived religion', null, 2),
  ('5273b1c0-592f-4e61-8871-dec00597c24a', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'd0dd2f88-8c9f-4fa2-8cad-6816d957023a', 'concept'::public.curated_course_node_type, 'Comparison and its limits', null, 3),
  ('9e2678b1-0d6b-4942-8285-ead81124486b', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '89322b0f-4140-4f17-b229-24f7dfea0dba', 'subtopic'::public.curated_course_node_type, 'Myth and symbolic worlds', 'Students examine how stories organize cosmology, identity, social order, and human purpose.', 1),
  ('48c6dc2b-e801-4720-b6d7-e0d7d439d34e', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '9e2678b1-0d6b-4942-8285-ead81124486b', 'concept'::public.curated_course_node_type, 'Creation and origin stories', null, 0);
