  ('10b18951-45c2-438f-94f0-764fb0e702ee', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'a235a5dd-aebf-446c-9589-bab7e37ff194', 'concept'::public.curated_course_node_type, 'Religion in public life', null, 3),
  ('6e62dd86-69fb-4db5-8114-526d7442d8af', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', null, 'topic'::public.curated_course_node_type, 'Language, Translation, Rhetoric, and Communication', 'Language is the medium through which much of the humanities travels. This unit helps students see language as form, power, translation, persuasion, identity, and historical record.', 8),
  ('6b112742-9720-4f68-9d6e-cfbe951d81e0', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '6e62dd86-69fb-4db5-8114-526d7442d8af', 'subtopic'::public.curated_course_node_type, 'Language and meaning', 'Students learn that words carry histories, assumptions, connotations, and cultural worlds.', 0),
  ('339166f8-a9c5-40e9-927e-f8893244f550', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '6b112742-9720-4f68-9d6e-cfbe951d81e0', 'concept'::public.curated_course_node_type, 'Denotation and connotation', null, 0),
  ('8cb61a97-2357-4eb3-8ff1-719ad66a2475', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '6b112742-9720-4f68-9d6e-cfbe951d81e0', 'concept'::public.curated_course_node_type, 'Metaphor and figurative meaning', null, 1),
  ('2bec29f5-9229-4992-a3e2-7c34a8c00397', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '6b112742-9720-4f68-9d6e-cfbe951d81e0', 'concept'::public.curated_course_node_type, 'Dialect, register, and code-switching', null, 2),
  ('493f0839-b7a1-480a-aa5f-832418561d0c', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '6b112742-9720-4f68-9d6e-cfbe951d81e0', 'concept'::public.curated_course_node_type, 'Language change and etymology', null, 3),
