  ('fbca3bb6-1d0e-4e05-a15f-8719a9cbbc5f', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'cd77406a-279d-4a0f-86be-230bfac2bbf6', 'concept'::public.curated_course_node_type, 'Adaptation and reception', null, 2),
  ('0a2b604a-d9c2-4224-bb62-dea562c7462d', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'cd77406a-279d-4a0f-86be-230bfac2bbf6', 'concept'::public.curated_course_node_type, 'Translator visibility and ethics', null, 3),
  ('7252a615-501e-4daa-960e-7aabc017a52c', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '6e62dd86-69fb-4db5-8114-526d7442d8af', 'subtopic'::public.curated_course_node_type, 'Rhetoric and persuasion', 'The unit teaches students to analyze how language moves audiences and shapes public life.', 2),
  ('2ce15761-66e5-4dbc-ac55-087ebc1c3e64', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '7252a615-501e-4daa-960e-7aabc017a52c', 'concept'::public.curated_course_node_type, 'Ethos, pathos, and logos', null, 0),
  ('9a49fba7-e820-4041-8c0e-c917a6f69ac4', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '7252a615-501e-4daa-960e-7aabc017a52c', 'concept'::public.curated_course_node_type, 'Style, arrangement, and audience', null, 1),
  ('b86c0ba1-7148-482e-87bb-cca71b5dde2f', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '7252a615-501e-4daa-960e-7aabc017a52c', 'concept'::public.curated_course_node_type, 'Propaganda and public argument', null, 2),
  ('abe0e5b4-64fd-4864-9785-8b96fcadab9b', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '7252a615-501e-4daa-960e-7aabc017a52c', 'concept'::public.curated_course_node_type, 'Digital rhetoric and attention', null, 3),
  ('d3eba38a-f9b2-4a7b-b0cb-a27c8b94572a', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', null, 'topic'::public.curated_course_node_type, 'Cross-Cultural Encounters, Global Traditions, and Comparative Humanities', 'A world-class humanities course must move beyond a single canon. This unit asks students to compare works across regions and traditions while avoiding flattening, exoticizing, or treating cultures as static.', 9),
  ('48e25cae-9b55-49e6-b2a3-11ad7a4e356a', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'd3eba38a-f9b2-4a7b-b0cb-a27c8b94572a', 'subtopic'::public.curated_course_node_type, 'Comparative method', 'Students learn how to compare responsibly: with specificity, context, and awareness of unequal power.', 0),
  ('c21e7cd8-d194-404a-b0f1-cc2fa3cf4aca', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '48e25cae-9b55-49e6-b2a3-11ad7a4e356a', 'concept'::public.curated_course_node_type, 'Common questions, different forms', null, 0),
  ('34ecf56d-05bb-4c76-a11d-4da174688747', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '48e25cae-9b55-49e6-b2a3-11ad7a4e356a', 'concept'::public.curated_course_node_type, 'Translation and mediation', null, 1),
  ('5fafc296-802d-45b6-99e9-ccf1fa9c42f0', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '48e25cae-9b55-49e6-b2a3-11ad7a4e356a', 'concept'::public.curated_course_node_type, 'Context before generalization', null, 2),
  ('e22b2884-1b8d-4664-8702-e3c353bdc4cd', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '48e25cae-9b55-49e6-b2a3-11ad7a4e356a', 'concept'::public.curated_course_node_type, 'Limits of analogy', null, 3),
