  ('fe241dda-1e91-452b-ab86-b8a08aebff54', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '7018bff1-e525-4838-82c7-1f40f4e36735', 'concept'::public.curated_course_node_type, 'Silk roads and oceanic exchange', null, 0),
  ('b564cd1f-acb3-45ae-9c23-028324fc7e93', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '7018bff1-e525-4838-82c7-1f40f4e36735', 'concept'::public.curated_course_node_type, 'Colonialism and cultural encounter', null, 1),
  ('6a66f720-8267-4468-ad2d-fe8f36da4f46', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '7018bff1-e525-4838-82c7-1f40f4e36735', 'concept'::public.curated_course_node_type, 'Diaspora and migration', null, 2),
  ('65cee746-3ef1-44f5-9888-ce7114a23575', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '7018bff1-e525-4838-82c7-1f40f4e36735', 'concept'::public.curated_course_node_type, 'Global modernisms and contemporary culture', null, 3),
  ('bddbd77a-de2a-4c88-9a46-e0b5b51b879b', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'd3eba38a-f9b2-4a7b-b0cb-a27c8b94572a', 'subtopic'::public.curated_course_node_type, 'Canon, inclusion, and curriculum', 'The unit asks who gets preserved, taught, translated, funded, and remembered.', 2),
  ('2d3d39da-1ba4-4844-a49f-f4b59a123bdb', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'bddbd77a-de2a-4c88-9a46-e0b5b51b879b', 'concept'::public.curated_course_node_type, 'Canon formation', null, 0),
  ('0f5207c1-5acc-4db9-bfe8-eb731e272811', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'bddbd77a-de2a-4c88-9a46-e0b5b51b879b', 'concept'::public.curated_course_node_type, 'Marginalized voices and recovery work', null, 1),
