insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('332864df-1d89-4ca7-b31f-ca20ba12ff62', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', null, 'topic'::public.curated_course_node_type, 'Aesthetics, Beauty, Taste, and Judgment', 'Aesthetics helps students ask how humans experience, value, and debate art, beauty, sublimity, ugliness, pleasure, and form. The unit links feeling to argument rather than treating taste as merely personal.', 10),
  ('d223bc64-f0c2-4f5d-83a3-083c102f316e', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '332864df-1d89-4ca7-b31f-ca20ba12ff62', 'subtopic'::public.curated_course_node_type, 'Theories of beauty and art', 'Students encounter classic and contemporary debates about what makes something art and how aesthetic value is argued.', 0),
  ('f4396248-5bd9-4f8c-a8ed-c20a168c7d1e', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'd223bc64-f0c2-4f5d-83a3-083c102f316e', 'concept'::public.curated_course_node_type, 'Beauty, sublimity, and the picturesque', null, 0),
  ('469bdde6-fc5b-4e7f-8446-1853ff8c8351', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'd223bc64-f0c2-4f5d-83a3-083c102f316e', 'concept'::public.curated_course_node_type, 'Mimesis, expression, form, and concept', null, 1),
  ('d116e118-4cdf-43b9-9bed-8669d1fe4f34', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'd223bc64-f0c2-4f5d-83a3-083c102f316e', 'concept'::public.curated_course_node_type, 'Art, craft, and design', null, 2),
  ('cfb30f43-1a8a-44d2-a09a-ffcd9019d08d', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'd223bc64-f0c2-4f5d-83a3-083c102f316e', 'concept'::public.curated_course_node_type, 'Institutional and social theories of art', null, 3),
  ('8b6d2ab1-0aa7-4b3e-b9fb-ca7f8890de05', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '332864df-1d89-4ca7-b31f-ca20ba12ff62', 'subtopic'::public.curated_course_node_type, 'Taste, judgment, and criticism', 'Students practice making evaluative claims that are more rigorous than preference.', 1),
  ('b6b407bc-063e-413f-95ac-ecac831d7c1a', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '8b6d2ab1-0aa7-4b3e-b9fb-ca7f8890de05', 'concept'::public.curated_course_node_type, 'Criteria and evidence', null, 0),
  ('619e5014-fcc5-476d-986d-a7c62e45168e', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '8b6d2ab1-0aa7-4b3e-b9fb-ca7f8890de05', 'concept'::public.curated_course_node_type, 'Reception and audience', null, 1),
  ('a208e25e-b623-4044-92cf-d566819dd02f', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '8b6d2ab1-0aa7-4b3e-b9fb-ca7f8890de05', 'concept'::public.curated_course_node_type, 'Criticism as public writing', null, 2),
  ('83e6a207-db4b-4e59-910f-f14cc93db88c', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '8b6d2ab1-0aa7-4b3e-b9fb-ca7f8890de05', 'concept'::public.curated_course_node_type, 'Disagreement and pluralism', null, 3),
  ('25def3eb-0300-4298-8b6d-35f92cafacab', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '332864df-1d89-4ca7-b31f-ca20ba12ff62', 'subtopic'::public.curated_course_node_type, 'Aesthetic experience in everyday life', 'The unit expands aesthetics beyond museums to media, design, food, fashion, nature, and digital culture.', 2),
  ('88f51415-0210-4747-b213-d517e333c6c0', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '25def3eb-0300-4298-8b6d-35f92cafacab', 'concept'::public.curated_course_node_type, 'Popular culture and taste hierarchies', null, 0),
  ('ef08943a-ff7d-4870-9c93-48fb6e233318', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '25def3eb-0300-4298-8b6d-35f92cafacab', 'concept'::public.curated_course_node_type, 'Design and everyday objects', null, 1),
  ('4accdcee-cd78-4b59-976c-877efba7771a', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '25def3eb-0300-4298-8b6d-35f92cafacab', 'concept'::public.curated_course_node_type, 'Environment and the sublime', null, 2),
  ('347d124c-e411-4ecd-b2dc-f3daaa644104', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '25def3eb-0300-4298-8b6d-35f92cafacab', 'concept'::public.curated_course_node_type, 'Attention, boredom, and wonder', null, 3),
  ('61c758f6-342e-4770-be4c-1a96154d23d3', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', null, 'topic'::public.curated_course_node_type, 'Modernity, Technology, Media, and the Digital Humanities', 'This unit connects the humanities to modern media systems and digital methods. Students consider how print, photography, film, the internet, data, and AI change cultural memory, authorship, interpretation, and access.', 11),
  ('5fd368f8-99bb-423b-9e6d-2546232ed34d', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '61c758f6-342e-4770-be4c-1a96154d23d3', 'subtopic'::public.curated_course_node_type, 'Media and modern life', 'Students learn that humanities objects are shaped by technologies of production and circulation.', 0),
  ('c68cb66c-8b20-4484-b0e4-de52caf2c01d', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '5fd368f8-99bb-423b-9e6d-2546232ed34d', 'concept'::public.curated_course_node_type, 'Manuscript, print, photography, film, and digital media', null, 0),
  ('585a4273-b850-4aeb-a4fc-e23a15d8021f', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '5fd368f8-99bb-423b-9e6d-2546232ed34d', 'concept'::public.curated_course_node_type, 'Mass culture and popular culture', null, 1),
  ('c8ba4876-06a4-451f-8a80-695d9d481623', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '5fd368f8-99bb-423b-9e6d-2546232ed34d', 'concept'::public.curated_course_node_type, 'Platforms and attention', null, 2),
  ('f5902846-9663-405b-96fd-2585d3ea6807', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '5fd368f8-99bb-423b-9e6d-2546232ed34d', 'concept'::public.curated_course_node_type, 'Authorship, remix, and participation', null, 3),
  ('26720ba0-794a-4d63-8ca3-2879062ea687', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '61c758f6-342e-4770-be4c-1a96154d23d3', 'subtopic'::public.curated_course_node_type, 'Digital humanities methods', 'Students receive an introductory sense of how digital tools can support, but not replace, interpretation.', 1),
  ('8d953adf-e757-4348-b766-5ef7adc33b15', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '26720ba0-794a-4d63-8ca3-2879062ea687', 'concept'::public.curated_course_node_type, 'Text encoding and digital editions', null, 0),
  ('b63f78c6-b391-4569-906e-d88d26cae41a', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '26720ba0-794a-4d63-8ca3-2879062ea687', 'concept'::public.curated_course_node_type, 'Mapping and timelines', null, 1),
  ('2c0564d0-b099-4910-a51a-ca5c6207f2dd', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '26720ba0-794a-4d63-8ca3-2879062ea687', 'concept'::public.curated_course_node_type, 'Text mining and distant reading', null, 2),
  ('d18bdb61-3ee4-4d62-bd53-52121a3dbb18', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '26720ba0-794a-4d63-8ca3-2879062ea687', 'concept'::public.curated_course_node_type, 'Digital archives and metadata', null, 3),
  ('83302bc2-3f4b-406b-b744-41230d1432bb', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '61c758f6-342e-4770-be4c-1a96154d23d3', 'subtopic'::public.curated_course_node_type, 'AI, interpretation, and human judgment', 'The goal is to examine new computational tools through humanistic questions about evidence, bias, creativity, and responsibility.', 2),
  ('e304b53a-f0ed-438b-8d2d-e042f57e0f4d', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '83302bc2-3f4b-406b-b744-41230d1432bb', 'concept'::public.curated_course_node_type, 'Generative AI and authorship', null, 0),
  ('e78af9e7-3915-4fc4-b4ee-f86d984d77b9', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '83302bc2-3f4b-406b-b744-41230d1432bb', 'concept'::public.curated_course_node_type, 'Algorithmic bias and cultural data', null, 1),
  ('7e19fcad-f4d6-4db2-aa68-4e9d99062cb0', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '83302bc2-3f4b-406b-b744-41230d1432bb', 'concept'::public.curated_course_node_type, 'Citation and disclosure', null, 2),
  ('c9fc2566-0d6e-49b9-9b28-49520cad5a46', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '83302bc2-3f4b-406b-b744-41230d1432bb', 'concept'::public.curated_course_node_type, 'What human interpretation still does', null, 3),
  ('2190ecc6-34c7-4da2-ad88-e43d516da469', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', null, 'topic'::public.curated_course_node_type, 'Power, Identity, Justice, and Public Humanities', 'The humanities study how cultures represent people, justify power, imagine justice, and contest exclusion. This unit brings identity, inequality, public memory, and civic dialogue into the center of interpretation.', 12),
  ('1fda4141-0221-4075-a297-d348ca437742', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '2190ecc6-34c7-4da2-ad88-e43d516da469', 'subtopic'::public.curated_course_node_type, 'Representation and identity', 'Students analyze how race, gender, class, sexuality, disability, nation, and religion are represented and debated.', 0),
  ('5b013883-58b0-485a-b033-059ab4f077ff', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '1fda4141-0221-4075-a297-d348ca437742', 'concept'::public.curated_course_node_type, 'Stereotype and counter-narrative', null, 0),
  ('9b87802c-7f8c-419e-b3f7-551a3b8c8b65', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '1fda4141-0221-4075-a297-d348ca437742', 'concept'::public.curated_course_node_type, 'Voice, agency, and authorship', null, 1),
  ('7e05c3b2-2e9b-46b6-a48e-a7a0b49f2d08', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '1fda4141-0221-4075-a297-d348ca437742', 'concept'::public.curated_course_node_type, 'Intersectionality', null, 2),
  ('a387c854-393b-4e2c-a967-762f49132796', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '1fda4141-0221-4075-a297-d348ca437742', 'concept'::public.curated_course_node_type, 'Embodiment and lived experience', null, 3),
  ('8230ea00-2b61-4014-bb29-1087663df95b', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '2190ecc6-34c7-4da2-ad88-e43d516da469', 'subtopic'::public.curated_course_node_type, 'Power, institutions, and cultural authority', 'Students ask how schools, museums, publishers, archives, media, and states shape what becomes visible.', 1),
  ('a7e07d03-8afd-4584-ba75-6005d7d4c2d9', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '8230ea00-2b61-4014-bb29-1087663df95b', 'concept'::public.curated_course_node_type, 'Gatekeeping and access', null, 0);
