  ('89de399a-6267-4c57-8929-335b9706adca', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', null, 'topic'::public.curated_course_node_type, 'Humanities Research, Sources, Citation, and Ethical Scholarship', 'This unit teaches students how to research responsibly in the humanities: finding sources, evaluating authority, building bibliographies, citing correctly, and treating cultural materials with care.', 13),
  ('a86c977e-7acc-4630-ba7a-a260a077852e', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', '89de399a-6267-4c57-8929-335b9706adca', 'subtopic'::public.curated_course_node_type, 'Research design', 'Students learn to move from curiosity to a focused, answerable, interpretive question.', 0),
