  ('c3724dba-d20c-47db-a2a2-6da63eea5d22', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', null, 'topic'::public.curated_course_node_type, 'Capstone Humanistic Interpretation: Curate, Present, Reflect, and Connect to Modern Life', 'The capstone asks students to synthesize the course by interpreting a humanities object or question for an audience. They build a polished project that demonstrates evidence, context, argument, reflection, and public communication.', 14),
  ('ade715e6-893b-4798-8161-c73756047e38', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'c3724dba-d20c-47db-a2a2-6da63eea5d22', 'subtopic'::public.curated_course_node_type, 'Project proposal and object selection', 'Students choose a text, artwork, performance, place, artifact, idea, or cultural debate that rewards humanistic analysis.', 0),
