  ('8ead38ec-b385-46ff-a2d0-2205e5254f45', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'ade715e6-893b-4798-8161-c73756047e38', 'concept'::public.curated_course_node_type, 'Ethical considerations', null, 3),
  ('b2c2796c-d432-4feb-b5c5-07b3f060cc15', 'c5d6e7f8-9a0b-4c66-9f56-6d7e8f9a0b66', 'c3724dba-d20c-47db-a2a2-6da63eea5d22', 'subtopic'::public.curated_course_node_type, 'Interpretive project design', 'Students translate research into a clear form such as an essay, exhibit, podcast, presentation, digital exhibit, or public-facing guide.', 1),
